CREATE TABLE `activity_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` bigint unsigned DEFAULT NULL COMMENT 'users.id — null for pre-auth events (failed login of an unknown account)',
  `actor_role` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'The actor''s role at action time',
  `action` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Vocabulary in App\\Models\\ActivityLog::ACTIONS',
  `target_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_id` bigint unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `context` json DEFAULT NULL COMMENT 'Action-specific details (e.g. failed attempts count, previous role)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Event time; immutable by design (no updated_at)',
  `old_values` json DEFAULT NULL COMMENT 'Values before the change — only the fields that changed',
  `new_values` json DEFAULT NULL COMMENT 'Values after the change — only the fields that changed',
  PRIMARY KEY (`id`),
  KEY `activity_logs_actor_id_index` (`actor_id`),
  KEY `activity_logs_action_index` (`action`),
  KEY `activity_logs_created_at_index` (`created_at`),
  KEY `activity_logs_target_type_index` (`target_type`)
) ENGINE=InnoDB AUTO_INCREMENT=4557 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
