--
-- Table structure for table `beneficiaries`
--

DROP TABLE IF EXISTS `beneficiaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `beneficiaries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name_of_farmer` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rsbsa_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `barangay_id` bigint unsigned DEFAULT NULL,
  `purok_id` bigint unsigned DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `location_source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `animal_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `animal_type_id` bigint unsigned DEFAULT NULL,
  `classification_id` bigint unsigned DEFAULT NULL,
  `ear_tag_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moa_signed` tinyint(1) DEFAULT NULL,
  `sex` enum('M','F') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'registration',
  `technician_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `beneficiaries_address_index` (`address`),
  KEY `beneficiaries_technician_id_index` (`technician_id`),
  KEY `beneficiaries_latitude_longitude_index` (`latitude`,`longitude`),
  KEY `beneficiaries_barangay_id_foreign` (`barangay_id`),
  KEY `beneficiaries_purok_id_foreign` (`purok_id`),
  KEY `beneficiaries_source_index` (`source`),
  KEY `beneficiaries_classification_id_foreign` (`classification_id`),
  KEY `beneficiaries_animal_type_id_classification_id_index` (`animal_type_id`,`classification_id`),
  KEY `beneficiaries_created_at_index` (`created_at`),
  KEY `beneficiaries_animal_type_index` (`animal_type`),
  CONSTRAINT `beneficiaries_animal_type_id_foreign` FOREIGN KEY (`animal_type_id`) REFERENCES `animal_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `beneficiaries_barangay_id_foreign` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`id`),
  CONSTRAINT `beneficiaries_classification_id_foreign` FOREIGN KEY (`classification_id`) REFERENCES `animal_classifications` (`id`) ON DELETE SET NULL,
  CONSTRAINT `beneficiaries_purok_id_foreign` FOREIGN KEY (`purok_id`) REFERENCES `puroks` (`id`),
  CONSTRAINT `beneficiaries_technician_id_foreign` FOREIGN KEY (`technician_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1024 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

